SELECT 종목약코드
     , 일자
     , 종목코드
     , FGSC지수코드
     , 시장구분
     , CASE
           WHEN 종목명 LIKE '%스팩%'
             OR UPPER(종목명) LIKE '%SPAC%'
             OR 종목명 LIKE '%기업인수목적%'
           THEN '1'
           ELSE '0'
       END AS SPAC_YN
  FROM DW_FNG_FGSC종목
 WHERE 시장구분 IN ('1', '2')
   AND 일자 IN (
       '20180131', '20180228', '20180330', '20180430', '20180531', '20180629',
       '20180731', '20180831', '20180928', '20181031', '20181130', '20181228',
